			}
		}
	}

	// Validate checkpoints_count
	if v.CheckpointsCount > 0 && metadata.CheckpointsCount != v.CheckpointsCount {
		env.T.Errorf("CommittedMetadata.CheckpointsCount = %d, want %d", metadata.CheckpointsCount, v.CheckpointsCount)
