	t.Helper()
	env := NewTestEnv(t)
	env.InitRepo()
	env.InitEntire()
	return env
}

// NewRepoWithCommit creates a TestEnv with a git repo, Entire, and an initial commit.
// The initial commit contains a README.md and .gitignore (excluding .entire/).
