func (env *TestEnv) GitCommitWithMetadata(message, metadataDir string) {
	env.T.Helper()

	// Format message with metadata trailer
	fullMessage := message + "\n\nEntire-Metadata: " + metadataDir + "\n"

	repo, err := git.PlainOpen(env.RepoDir)
