			t.Error("NativeData is empty, want transcript content")
		}

		// Verify ModifiedFiles computed
		if len(session.ModifiedFiles) != 2 {
			t.Errorf("ModifiedFiles = %v, want 2 files (main.go, util.go)", session.ModifiedFiles)
		}
